create table if not exists public.dp_page_visits(id bigint generated always as identity primary key,visitor_id text not null,session_id text not null,page_path text not null,referrer text default '',device_type text default 'unknown',created_at timestamptz not null default now());create index if not exists dp_page_visits_created_idx on public.dp_page_visits(created_at desc);create table if not exists public.dp_chat_messages(id bigint generated always as identity primary key,visitor_id text not null,session_id text not null,page_path text not null,role text not null check(role in('user','assistant')),message text not null,created_at timestamptz not null default now());create index if not exists dp_chat_messages_created_idx on public.dp_chat_messages(created_at desc);alter table public.dp_page_visits enable row level security;alter table public.dp_chat_messages enable row level security;